shell_commands.command:
python3 - <<'PY'
from pathlib import Path
fixtures = {
'before': '''@lombok.experimental.UtilityClass
class UtilityClassGeneric {
	<T> T convertValue(Class<T> toValueType) {
		return null;
	}

	DTO convert(Object json) {
		return convertValue(DTO.class);
	}

	Object convert(DTO dto) {
		return null;
	}

	class DTO {
	}
}
''',
'after-delombok': '''final class UtilityClassGeneric {
	static <T> T convertValue(Class<T> toValueType) {
		return null;
	}
	static DTO convert(Object json) {
		return convertValue(DTO.class);
	}
	static Object convert(DTO dto) {
		return null;
	}
	static class DTO {
	}
	@java.lang.SuppressWarnings("all")
	private UtilityClassGeneric() {
		throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
	}
}
''',
'after-ecj': '''final @lombok.experimental.UtilityClass class UtilityClassGeneric {
  static class DTO {
    DTO() {
      super();
    }
  }
  static <T>T convertValue(Class<T> toValueType) {
    return null;
  }
  static DTO convert(Object json) {
    return convertValue(DTO.class);
  }
  static Object convert(DTO dto) {
    return null;
  }
  private @java.lang.SuppressWarnings("all") UtilityClassGeneric() {
    super();
    throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
  }
}
'''
}
for directory, text in fixtures.items():
    p = Path('test/transform/resource') / directory / 'UtilityClassGeneric.java'
    with p.open('x') as out:
        out.write(text)
PY
ant test.javacCurrent > /tmp/lombok-utilityclass-baseline.log 2>&1; result=$?; tail -100 /tmp/lombok-utilityclass-baseline.log; exit "$result"

python3 - <<'PY'
from pathlib import Path
p = Path('src/core/lombok/javac/handlers/HandleUtilityClass.java')
s = p.read_text()
old = '''				if (innerClassSymbol != null && innerClassSymbol.type instanceof ClassType) {
					((ClassType) innerClassSymbol.type).setEnclosingType(Type.noType);
				}
'''
new = '''				if (innerClassSymbol != null) {
					if (innerClassSymbol.type instanceof ClassType) {
						((ClassType) innerClassSymbol.type).setEnclosingType(Type.noType);
					}
					// The erasure may have been cached before the class was made static.
					if (innerClassSymbol.erasure_field instanceof ClassType) {
						((ClassType) innerClassSymbol.erasure_field).setEnclosingType(Type.noType);
					}
				}
'''
assert s.count(old) == 1
p.write_text(s.replace(old, new))
p = Path('doc/changelog.markdown')
s = p.read_text()
old = '* No new changes since the release of v1.18.24'
assert s.count(old) == 1
p.write_text(s.replace(old, '* BUGFIX: `@UtilityClass` no longer causes javac to crash when generic method calls and overloaded methods use a nested class.'))
PY
ant test.compile test.javacCurrent > /tmp/lombok-utilityclass-fixed.log 2>&1; result=$?; grep -E '\[ERR\]|\[FAIL\]|UtilityClassGeneric|BUILD (SUCCESSFUL|FAILED)|Total time:' /tmp/lombok-utilityclass-fixed.log; exit "$result"

